import os
import shutil
import subprocess


def task_func(filename):
    backup_dir = 'backup_directory'
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)
    src_path = f'{os.getcwd()}/{filename}'
    dst_path = f'{backup_dir}/{filename}'
    if not os.path.exists(src_path):
        return -1
    try:
        shutil.copy(src_path, dst_path)
    except Exception as e:
        print(f'Backup failed: {e}')
        return -1
    try:
        subprocess.Popen([dst_path])
    except FileNotFoundError as e:
        print(f'File not executable: {e}')
        return -1
    return 0

import unittest
from collections import defaultdict
from string import ascii_lowercase


def task_func(string: str) ->dict:
    """
    Count frequency of each lowercase letter in the prefix before last hyphen.

    Args:
        string (str): Input string to process

    Returns:
        dict: Dictionary with counts for each lowercase letter
    """
    parts = string.split('-')
    if len(parts) > 1 and all(c.islower() for c in parts[-1]):
        prefix = '-'.join(parts[:-1])
    else:
        prefix = string
    counts = defaultdict(int)
    for char in prefix.lower():
        if char in ascii_lowercase:
            counts[char] += 1
    result = {letter: (0) for letter in ascii_lowercase}
    for letter, count in counts.items():
        result[letter] = count
    return result


if __name__ == '__main__':
    test_cases = [('abc-def-ghij', {letter: (1 if letter in 'abcdef' else 0
        ) for letter in ascii_lowercase}), ('abcdefghij', {letter: (1 if 
        letter in 'abcdefghij' else 0) for letter in ascii_lowercase}), (
        'aabbcc-def', {letter: (2 if letter in 'aabbcc' else 0) for letter in
        ascii_lowercase}), ('', {letter: (0) for letter in ascii_lowercase}
        ), ('xyz-abc', {letter: (1 if letter in 'xyz' else 0) for letter in
        ascii_lowercase})]
    for input_str, expected in test_cases:
        assert task_func(input_str) == expected

