import logging
import requests
import numpy as np
logging.basicConfig(level=logging.INFO)


def task_func(word):
    if not isinstance(word, str):
        raise TypeError('Input must be a string')
    try:
        sanitized = ''.join([c for c in word if c.isalpha()])
        sanitized_dup = ''.join(filter(str.isalpha, word))
        if sanitized != sanitized_dup:
            logging.warning('Sanitization mismatch')
        result = {}
        arr = np.array(list(sanitized))
        for i in range(len(arr) - 1):
            pair = arr[i] + arr[i + 1]
            result[pair] = result.get(pair, 0) + 1
        return result
    except Exception as e:
        logging.error(f'Error processing word: {e}')
        return {}

