import pandas as pd
import random


def task_func(data_list, seed=None):
    result = []
    for s in data_list:
        parts = [part.strip() for part in s.replace(' ', '').split(',')]
        if len(parts) <= 1 or not seed:
            shuffled = s
        else:
            random.seed(seed)
            if len(parts) > 1:
                random.shuffle(parts)
                shuffled = ', '.join(parts)
            else:
                shuffled = s
        result.append({'Original String': s, 'Shuffled String': shuffled})
    return pd.DataFrame(result)

