import json
from datetime import datetime
import numpy as np
from decimal import Decimal


def task_func(my_obj):
    """Serialize an object to JSON, handling datetime, numpy.ndarray, and Decimal."""


    class CustomEncoder(json.JSONEncoder):

        def default(self, obj):
            handlers = [(datetime, lambda o: o.isoformat()), (np.ndarray, 
                lambda o: o.tolist()), (Decimal, lambda o: str(o))]
            for typ, handler in handlers:
                if isinstance(obj, typ):
                    return handler(obj)
            return super().default(obj)
    return json.dumps(my_obj, cls=CustomEncoder)

