import random


def task_func(t, n):
    """Return a random combination of length n from tuple t."""

    def rec(start, k):
        if k == 0:
            yield ()
        else:
            for i in range(start, len(t) - k + 1):
                for rest in rec(i + 1, k - 1):
                    yield (t[i],) + rest
    combos = list(rec(0, n))
    return random.choice(combos)

