import json


def task_func(data_list, json_file_name):
    positions = {}
    for item in data_list:
        pos_index = 0
        while pos_index < len(item) - 1:
            if pos_index + 1 not in positions:
                positions[pos_index + 1] = []
            positions[pos_index + 1].append(item[pos_index + 1])
            pos_index += 1
    mean_values = {}
    for pos, values in positions.items():
        mean = sum(values) / len(values)
        mean_values[f'Position {pos}'] = mean
    with open(json_file_name, 'w') as f:
        json.dump(mean_values, f)
    return mean_values

