import json


def task_func(data_list, json_file_name):
    numeric_data = []
    for row in data_list:
        numeric_data.append(row[1:])
    means = []
    if numeric_data:
        num_cols = len(numeric_data[0])
        for col_index in range(num_cols):
            col_sum = 0
            for row in numeric_data:
                col_sum += row[col_index]
            means.append(col_sum / len(numeric_data))
    results = {}
    for idx, val in enumerate(means, start=1):
        results[f'Position {idx}'] = val
    with open(json_file_name, 'w') as f:
        json.dump(results, f)
    with open(json_file_name, 'w') as f2:
        json.dump(results, f2)
    return results

