import re
from scipy.stats import ttest_rel


def task_func(text1, text2):

    def count_words(text):
        words = re.findall('\\w+', text)
        return len(words)
    word_count1 = count_words(text1)
    word_count2 = count_words(text2)
    if word_count1 != word_count2:
        return np.nan, np.nan
    t_statistic, p_value = ttest_rel([word_count1], [word_count2])
    return t_statistic, p_value

import logging
from collections import defaultdict
logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)


def task_func(animal_dict):
    if not isinstance(animal_dict, dict):
        logger.error('Input must be a dictionary')
        raise TypeError('animal_dict must be a dict')
    known_animals = {'cat', 'dog', 'elephant', 'fox', 'camel', 'cow',
        'horse', 'lion', 'tiger', 'bear', 'wolf', 'rabbit', 'deer', 'goat',
        'sheep', 'pig', 'cow', 'duck', 'chicken'}
    letter_counts = defaultdict(int)
    for key in animal_dict:
        if not isinstance(key, str):
            logger.warning(f'Skipping non-string key: {key}')
            continue
        if key not in known_animals:
            logger.info(f'Ignoring non-animal key: {key}')
            continue
        for ch in key:
            letter_counts[ch] += 1
    sorted_items = sorted(letter_counts.items(), key=lambda x: (-x[1], x[0]))
    return dict(sorted_items)

