import unicodedata
import requests


def task_func(username):
    URL = 'https://api.github.com/users/'
    try:
        response = requests.get(URL + username)
        response.raise_for_status()
        user_data = response.json()
    except requests.exceptions.RequestException as e:
        raise Exception(
            f"Failed to fetch user data for '{username}'. HTTP status: {e.response.status_code} - {e.response.reason}"
            ) from e
    normalization_dict = {'login': str, 'id': int, 'node_id': str,
        'avatar_url': str, 'gravatar_id': str, 'url': str, 'html_url': str,
        'followers_url': str, 'following_url': str, 'gists_url': str,
        'starred_url': str, 'subscriptions_url': str, 'organizations_url':
        str, 'repos_url': str, 'events_url': str, 'received_events_url':
        str, 'type': str, 'site_admin': bool}
    normalized_data = {}
    for key in user_data:
        if isinstance(user_data[key], str):
            normalized_value = unicodedata.normalize('NFKD', user_data[key]
                ).encode('ascii', errors='ignore').decode()
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = user_data[key]
    return normalized_data

