import random
from collections import defaultdict


def task_func(num_strings, string_length):

    def generate_strings(n, length):
        return [''.join(random.choices('abcdefghijklmnopqrstuvwxyz', k=
            length)) for _ in range(n)]

    def count_characters(strings_list):
        char_count = defaultdict(int)
        for s in strings_list:
            for c in s:
                char_count[c] += 1
        return char_count

    def sort_by_frequency(char_dict):
        sorted_chars = sorted(char_dict.items(), key=lambda x: (-x[1], x[0]))
        return sorted_chars
    strings = generate_strings(num_strings, string_length)
    counts = count_characters(strings)
    result = sort_by_frequency(counts)
    return result

