import pandas as pd
import random
from typing import List
PLANETS = ['Mercury', 'Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn',
    'Uranus', 'Neptune']
ELEMENTS = ['Hydrogen', 'Helium', 'Lithium', 'Beryllium', 'Boron', 'Carbon',
    'Nitrogen', 'Oxygen']


def task_func() ->pd.DataFrame:
    data = [[f'{p}:{e}' for e in ELEMENTS] for p in PLANETS]
    return pd.DataFrame(data, columns=ELEMENTS)


class TaskFuncAlternative:

    def __init__(self):
        self.planets = PLANETS
        self.elements = ELEMENTS

    def generate_pairs(self) ->List[List[str]]:
        return [[f'{p}:{e}' for e in self.elements] for p in self.planets]

    def create_dataframe(self, pairs: List[List[str]]) ->pd.DataFrame:
        return pd.DataFrame(pairs, columns=self.elements)


def task_func_alternative() ->pd.DataFrame:
    generator = TaskFuncAlternative()
    pairs = generator.generate_pairs()
    return generator.create_dataframe(pairs)

