import numpy as np


def task_func(myList):
    if not myList:
        return np.array([])
    min_val = min(myList)
    max_val = max(myList)
    range_val = max_val - min_val
    if range_val == 0:
        normalized = [(0.0) for _ in myList]
    else:
        normalized = [((x - min_val) / range_val) for x in myList]
    return np.array(normalized)

