import numpy as np


def task_func(myList):
    if not isinstance(myList, list):
        raise TypeError('Input must be a list')
    for item in myList:
        if not isinstance(item, (int, float)):
            raise TypeError('List elements must be numeric')
    normalized_array = np.array(myList)
    min_val = np.min(normalized_array)
    max_val = np.max(normalized_array)
    if max_val == min_val:
        return np.zeros_like(normalized_array)
    normalized_array = (normalized_array - min_val) / (max_val - min_val)
    return normalized_array.flatten()

