import random


def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    word_count = random.randint(MIN_WORDS, MAX_WORDS)
    words = []
    for _ in range(word_count):
        words.append(random.choice(WORDS_POOL))
    if len(words) % 2 == 0:
        first_half = words[:len(words) // 2]
        second_half = first_half[::-1]
    else:
        first_half = words[:len(words) // 2 + 1]
        second_half = first_half[:-1][::-1]
    palindrome_words = first_half + second_half
    return ' '.join(palindrome_words)

import math
import logging
logging.basicConfig(level=logging.INFO)


def task_func(points):
    """Calculate Euclidean distances between consecutive 2D points."""
    if not isinstance(points, list):
        raise TypeError('points must be a list')
    distances = []
    prev = None
    for idx, pt in enumerate(points):
        if not isinstance(pt, tuple):
            raise TypeError(f'point at index {idx} is not a tuple')
        if len(pt) == 1:
            x = y = pt[0]
        elif len(pt) == 2:
            x, y = pt
        else:
            raise ValueError(f'point at index {idx} must have 1 or 2 elements')
        if not all(isinstance(v, (int, float)) for v in (x, y)):
            raise TypeError(f'coordinates at index {idx} must be numeric')
        if prev is not None:
            dx = x - prev[0]
            dy = y - prev[1]
            distances.append(math.hypot(dx, dy))
        prev = x, y
    return distances

