import pandas as pd
import numpy as np


def task_func(array):
    if not array:
        raise IndexError('Input array cannot be empty')
    if not all(isinstance(row, list) for row in array):
        raise TypeError('Each element of the input must be a list')
    for row in array:
        if not all(isinstance(x, (int, float)) for x in row):
            raise TypeError('All elements must be integers or floats')
    num_columns = len(array[0])
    columns = [chr(ord('A') + i) for i in range(num_columns)]
    df = pd.DataFrame(array, columns=columns)

    def compute_distance(row1, row2):
        return np.sqrt(np.sum((row1 - row2) ** 2))
    num_rows = len(df)
    distance_matrix = pd.DataFrame(index=df.index, columns=df.index)
    for i in range(num_rows):
        for j in range(i + 1):
            if i == j:
                distance = 0.0
            else:
                distance = compute_distance(df.iloc[i], df.iloc[j])
            distance_matrix.iloc[i, j] = distance
            distance_matrix.iloc[j, i] = distance
    return df, distance_matrix

