from pathlib import Path
import glob


def task_func(pattern: str, directory: str, extensions: list[str]) ->list[Path
    ]:
    """Find files matching a regex pattern in their contents within specified directory and file extensions."""
    matched_files = []
    for ext in extensions:
        search_pattern = os.path.join(directory, ext)
        found_files = glob.glob(search_pattern)
        for file_path in found_files:
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    content = f.read().lower()
                    if re.search(pattern.lower(), content):
                        matched_files.append(Path(file_path).resolve())
            except IOError:
                pass
    return matched_files

import numpy as np


def task_func(myList):

    def find_min_max(arr):
        min_val = max_val = arr[0]
        for num in arr:
            if num < min_val:
                min_val = num
            if num > max_val:
                max_val = num
        return min_val, max_val

    def normalize_value(value, min_v, max_v):
        if max_v - min_v == 0:
            return 0.0
        return (value - min_v) / (max_v - min_v)
    if not myList:
        return np.array([])
    min_val, max_val = find_min_max(myList)
    normalized = [normalize_value(num, min_val, max_val) for num in myList]
    return np.array(normalized)

import os
import re
from pathlib import Path


def task_func(source_directory, target_directory, pattern='\\d{4}'):

    def get_matching_files(directory, pattern):
        files = []
        for file in os.listdir(directory):
            if re.search(pattern, file):
                files.append(file)
        return files

    def move_file(src_path, dst_path, file_name):
        src = os.path.join(src_path, file_name)
        dst = os.path.join(dst_path, file_name)
        os.rename(src, dst)
    source_exists = os.path.exists(source_directory)
    if not source_exists:
        return 0
    target_created = os.path.exists(target_directory)
    if not target_created:
        os.makedirs(target_directory)
    matching_files = get_matching_files(source_directory, pattern)
    moved_count = 0
    for file in matching_files:
        move_file(source_directory, target_directory, file)
        moved_count += 1
    return moved_count

