import gzip
import difflib
from io import TextIOWrapper


def task_func(file_path1, file_path2):
    """
    Compares the contents of two gzip files and returns a string describing their differences.
    Uses difflib to compute differences efficiently.
    Returns an empty string if files are identical.
    """

    def read_gzip_file(file_path):
        """Reads content from a gzip file."""
        with gzip.open(file_path, 'rt') as f:
            return f.read()
    try:
        content1 = read_gzip_file(file_path1)
        content2 = read_gzip_file(file_path2)
        diff = difflib.ndiff(content1.splitlines(), content2.splitlines())
        return '\n'.join(line for line in diff if line.startswith(('-', '+')))
    except FileNotFoundError as e:
        raise FileNotFoundError(f'File not found: {e.filename}') from None

