from collections import Counter
import os


def task_func(json_files_path, key):
    """
    Count the occurrence of a particular key in all json files in a specified directory and return a dictionary with the values of the specified key and their counts.
    """
    counts = {}
    for filename in os.listdir(json_files_path):
        if filename.endswith('.json'):
            filepath = os.path.join(json_files_path, filename)
            try:
                with open(filepath, 'r') as f:
                    data = json.load(f)
                    if key in data:
                        value = data[key]
                        if value in counts:
                            counts[value] += 1
                        else:
                            counts[value] = 1
            except FileNotFoundError:
                pass
            except json.JSONDecodeError:
                pass
    return dict(counts)

