def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    word_count = random.randint(MIN_WORDS, MAX_WORDS)
    words = []
    for _ in range(word_count):
        words.append(random.choice(WORDS_POOL))
    if len(words) % 2 == 0:
        first_half = words[:len(words) // 2]
        second_half = first_half[::-1]
    else:
        first_half = words[:len(words) // 2 + 1]
        second_half = first_half[:-1][::-1]
    palindrome_words = first_half + second_half
    return ' '.join(palindrome_words)

