def task_func(MIN_WORDS, MAX_WORDS, WORDS_POOL):
    pool_set = set(WORDS_POOL)
    length = random.randint(MIN_WORDS, MAX_WORDS)
    first_half = []
    for _ in range(length // 2):
        first_half.append(random.choice(list(pool_set)))
    middle_word = None
    if length % 2:
        middle_word = random.choice(list(pool_set))
    second_half = []
    for w in first_half[::-1]:
        second_half.append(w)
    sentence_words = first_half
    if middle_word:
        sentence_words.append(middle_word)
    sentence_words.extend(second_half)
    return ' '.join(sentence_words)

