        return len(re.findall('\\berror\\b', content, flags=re.IGNORECASE))

    def get_relpath(file_path: str, base_dir: str) ->str:
        file = pathlib.Path(file_path)
        base = pathlib.Path(base_dir)
        return str(file.relative_to(base))
    result: Dict[str, int] = {}
    if not pathlib.Path(dir_path).is_dir():
        raise ValueError('Specified directory does not exist.')
    txt_files = list(pathlib.Path(dir_path).rglob('*.txt'))
    for file in txt_files:
        try:
            content = file.read_text()
            count = count_errors(content)
            relpath = get_relpath(str(file), dir_path)
            result[relpath] = count
        except Exception as e:
            pass
    return result

