import re
import os
from collections import defaultdict


def task_func(dir_path):
    file_info = FileScanner().scan_directory(dir_path)
    error_counts = ErrorCounter().count_errors(file_info)
    return error_counts


class FileScanner:

    def scan_directory(self, directory):
        if not os.path.isdir(directory):
            raise ValueError('Specified directory does not exist.')
        file_paths = []
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.txt'):
                    file_path = os.path.join(root, file)
                    relative_path = os.path.relpath(file_path, directory)
                    file_paths.append((relative_path, file_path))
        return file_paths


class ErrorCounter:

    def count_errors(self, file_info):
        error_counts = defaultdict(int)
        for relative_path, file_path in file_info:
            try:
                with open(file_path, 'r') as f:
                    content = f.read()
                matches = re.findall('\\berror\\b', content, flags=re.
                    IGNORECASE)
                error_counts[relative_path] = len(matches)
            except Exception:
                pass
        return dict(error_counts)

