import pandas as pd
import random


def task_func(data_list, seed=None):
    if seed is not None:
        random.seed(seed)
    if not all(isinstance(item, str) for item in data_list):
        raise TypeError('data_list must contain only strings')
    df = pd.DataFrame({'Original String': data_list})

    def apply_operation(s):
        substrings = s.split(', ')
        operation = random.choice(['remove', 'replace', 'shuffle', 'randomize']
            )
        if operation == 'remove':
            if len(substrings) > 1:
                random_substring = random.choice(substrings)
                substrings.remove(random_substring)
                return ', '.join(substrings)
            else:
                return s
        elif operation == 'replace':
            if len(substrings) > 0:
                index = random.randint(0, len(substrings) - 1)
                substrings[index] = 'random_string'
                return ', '.join(substrings)
            else:
                return s
        elif operation == 'shuffle':
            if len(substrings) > 0:
                random.shuffle(substrings)
                return ', '.join(substrings)
            else:
                return s
        elif operation == 'randomize':
            if len(substrings) > 0:
                positions = random.sample(range(len(substrings)), len(
                    substrings))
                return ', '.join([substrings[i] for i in positions])
            else:
                return s
    modified_list = []
    for s in data_list:
        modified_s = apply_operation(s)
        modified_list.append(modified_s)
    df['Modified String'] = modified_list
    return df

