                f'Failed to convert list for file {selected_file}: {e}')
            return pd.DataFrame(columns=['email', 'list', 'sum', 'mean',
                'median']), None
        try:
            df['sum'] = df['list'].apply(lambda x: sum(x))
            df['mean'] = df['list'].apply(lambda x: np.mean(x))
            df['median'] = df['list'].apply(lambda x: np.median(x))
        except TypeError as e:
