            lines = f.readlines()
    except FileNotFoundError:
        raise
    except UnicodeDecodeError:
        raise
    result = []
    for line in lines:
        matched = False
        for kw in keywords:
            if kw in line:
                parts = line.strip().split(maxsplit=2)
                if len(parts) >= 3:
                    formatted = (
                        f'{kw:>{20}} : {parts[1]:>{20}} : {parts[2]:>{20}}')
                    result.append(formatted)
                else:
                    result.append(f'Line format unexpected: {line.strip()}')
                matched = True
                break
        if not matched:
            continue
    return result if result else []

import json
import os
from pathlib import Path
from typing import List, Optional


def task_func(directory: str, string: str) ->List[str]:

    def is_json_file(file_path: str) ->bool:
        try:
            with open(file_path, 'r') as f:
                json.load(f)
                return True
        except (IOError, json.JSONDecodeError):
            return False

    def search_file(file_path: str) ->Optional[str]:
        if string in file_data:
            return str(file_path)
        return None
    result_files = []
    directory_path = Path(directory).resolve()
    for root, _, files in os.walk(str(directory_path)):
        for file in files:
            file_path = os.path.join(root, file)
            if is_json_file(file_path):
                try:
                    with open(file_path, 'r') as f:
                        file_data = json.load(f)
                        result = search_file(file_path)
                        if result:
                            result_files.append(result)
                except Exception as e:
                    continue
    return result_files

import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt
import numpy as np


def task_func(array):
    if not array:
        raise ValueError
    columns = ['A', 'B', 'C', 'D', 'E']
    data_dict = {col: [] for col in columns}
    for row in array:
        if len(row) != 5:
            raise ValueError
        for i, val in enumerate(row):
            if not isinstance(val, (int, float)):
                raise ValueError
            data_dict[columns[i]].append(val)
    df = pd.DataFrame(data_dict)
    corr_matrix = df.corr()
    heatmap = sns.heatmap(corr_matrix)
    return df, heatmap

import json
from statistics import mean
from typing import List, Dict, Any
from collections import defaultdict


def task_func(data_list: List[tuple], json_file_name: str='mean_values.json'
    ) ->Dict[str, Any]:
    position_data = defaultdict(list)
    for data in data_list:
        if not isinstance(data, tuple) or len(data) < 1:
            continue
        pos = str(data[0])
        values = list(data[1:])
        for i, value in enumerate(values):
            try:
                num_value = float(value)
                position_data[f'Position {i + 1}'].append(num_value)
            except (ValueError, TypeError):
                pass
    results = {}
    for pos_key in position_data:
        values = position_data[pos_key]
        if not values:
            continue
        try:
            mean_val = mean(values)
            results[pos_key] = float(mean_val)
        except statistics.StatisticsError:
            results[pos_key] = None
    with open(json_file_name, 'w') as f:
        json.dump(results, f)
    return results

