import numpy as np
import pandas as pd
from sklearn.preprocessing import StandardScaler


def task_func(data=None):
    if data is None:
        data = np.random.rand(100, 5)
    replaced = np.where(data < 0.5, 0, data)
    scaled = StandardScaler().fit_transform(replaced)
    return pd.DataFrame(scaled)
